class Solution {
public:
    int checkRecord(int n) {
        const int MOD = 1e9 + 7;
        vector<vector<long>> dp(2, vector<long>(3));
        dp[0][0] = 1;

        for (int i = 0; i < n; ++i) {
            vector<vector<long>> new_dp(2, vector<long>(3));
            for (int a = 0; a < 2; ++a) {
                for (int l = 0; l < 3; ++l) {
                    long val = dp[a][l];
                    if (val == 0) continue;
                    new_dp[a][0] = (new_dp[a][0] + val) % MOD;
                    if (a + 1 < 2)
                        new_dp[a + 1][0] = (new_dp[a + 1][0] + val) % MOD;
                    if (l + 1 < 3)
                        new_dp[a][l + 1] = (new_dp[a][l + 1] + val) % MOD;
                }
            }
            dp = new_dp;
        }

        long total = 0;
        for (auto& row : dp)
            for (auto& val : row)
                total = (total + val) % MOD;

        return (int)total;
    }
};
